package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextUniversalFrozenConstraints.Proof;
import org.kanger.ContextUniversalCompoundExchange.*;
import org.kanger.ContextWitnessResultTransport.*;

/** Actual prior/barrier ownership, unchanged exception contract, and fresh forged-evidence checks. */
public final class ContextUniversalCompoundRebaseSessionRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Action{void run();}
    static RuntimeException failure(Action a){try{a.run();}catch(IllegalArgumentException|IllegalStateException e){return e;}throw new AssertionError("Expected original throwing refusal");}
    static void reject(Exchange prior,ConstraintBarrier barrier,int work,String why){RuntimeException old=failure(()->ContextUniversalCompoundExchange.rebase(prior,barrier,work));SessionRebase[] prefix={null};RuntimeException actual=failure(()->prefix[0]=ContextUniversalCompoundExchange.rebaseWithValidationReuse(prior,barrier,work,4096));require(prefix[0]==null&&actual.getClass()==old.getClass()&&Objects.equals(actual.getMessage(),old.getMessage()),why+": "+actual);}
    static SessionRebase yes(Exchange prior,ConstraintBarrier barrier){Exchange old=ContextUniversalCompoundExchange.rebase(prior,barrier,WORK);SessionRebase actual=ContextUniversalCompoundExchange.rebaseWithValidationReuse(prior,barrier,WORK,4096);Exchange e=actual.exchange;require(actual.metrics.entries==0&&actual.metrics.verified>0&&actual.metrics.work<WORK,"fresh bounded authentication closed before return");require(e.x==old.x&&e.prior==old.prior&&e.barrier==old.barrier&&e.common==old.common&&e.checks==old.checks&&e.clauses==old.clauses&&e.maximumClauses==old.maximumClauses&&e.maximumAlternatives==old.maximumAlternatives&&e.maximumDepth==old.maximumDepth&&e.prior==prior&&e.barrier==barrier&&e.common==barrier.packet,"same actual rebase ownership and unchanged complete unit list");require(ContextUniversalCompoundExchange.sameContents(e,old,WORK),"exact symbolic Source-depth contents equal");ContextUniversalCompoundExchange.check(e,e.x,e.common,64,ContextGroundProductionRounds.budget(WORK));++checks;return actual;}
    static void mutate(Exchange prior,ConstraintBarrier barrier,Object owner,String field,Object value,String why)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(field);f.setAccessible(true);Object saved=f.get(owner);f.set(owner,value);try{reject(prior,barrier,WORK,why);}finally{f.set(owner,saved);}}
    static void cases()throws Exception {
        for(boolean symbolic:Arrays.asList(false,true)){ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(symbolic,false);for(ContextUniversalGroupedRounds.Round r:f.trace.history)yes(r.compoundOutput.prior,r.barrier);ContextUniversalGroupedRounds.Round last=f.trace.history.get(f.trace.history.size()-1);Exchange p=last.compoundOutput.prior;reject(null,last.barrier,WORK,"missing actual prior");reject(p,null,WORK,"missing fixed barrier");reject(p,last.barrier,0,"original positive work guard");reject(p,last.barrier,1,"fresh work1 after success cannot reuse old authentication");reject(p,f.trace.history.get(0).barrier,WORK,"same-content older fixed barrier is not actual current ledger");SessionRebase cap1=ContextUniversalCompoundExchange.rebaseWithValidationReuse(p,last.barrier,WORK,1);require(cap1.metrics.entries==0&&cap1.metrics.peakEntries==1&&cap1.metrics.capacityBypass>0&&ContextUniversalCompoundExchange.sameContents(cap1.exchange,last.compoundOutput,WORK),"capacity1 performs real validation fallback");Map<Cut,ConstraintTransfer> missing=new LinkedHashMap<>(last.barrier.branches);missing.remove(missing.keySet().iterator().next());mutate(p,last.barrier,last.barrier,"branches",missing,"complete cut inventory required");ConstraintTransfer transfer=last.barrier.branches.values().iterator().next();mutate(p,last.barrier,transfer,"before",f.input,"old actual common input cannot replace current branch basis");require(failure(()->ContextUniversalCompoundExchange.rebaseWithValidationReuse(p,last.barrier,WORK,0)) instanceof IllegalArgumentException,"bounded capacity required");}
        ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(false,true);for(ContextUniversalGroupedRounds.Round r:f.trace.history)yes(r.compoundOutput.prior,r.barrier);ContextUniversalGroupedRounds.Round first=f.trace.history.get(0);Exchange p=first.compoundOutput.prior;org.kanger.ContextUniversalFrozenConstraints.Result groupedOwner=first.checks.values().stream().filter(r->r.proofs.stream().anyMatch(v->v.grouped!=null)).findFirst().get();Proof proof=groupedOwner.proofs.stream().filter(v->v.grouped!=null).findFirst().get();mutate(p,first.barrier,proof,"support",new Support(proof.support.sources,proof.support.depth+1),"new invocation rejects forged grouped grade after success");mutate(p,first.barrier,groupedOwner,"groupedInputs",Collections.emptyList(),"full grouped manifest required after previous successful invocation");yes(p,first.barrier);
        mutate(p,first.barrier,p,"clauses",Collections.emptyList(),"missing entire compound inventory after success");List<ResidualProof> duplicate=new ArrayList<>(p.clauses);duplicate.add(duplicate.get(0));mutate(p,first.barrier,p,"clauses",duplicate,"duplicate compound exact-Source inventory after success");mutate(p,first.barrier,p,"maximumClauses",0,"sealed enumeration policy checked anew");mutate(p,first.barrier,p,"maximumDepth",0,"sealed depth cannot hide actual deeper clause");yes(p,first.barrier);
        ContextUniversalGroupedChainAuditRunner.Fixture symbolic=new ContextUniversalGroupedChainAuditRunner.Fixture(true,false);ContextUniversalGroupedRounds.Round r=symbolic.trace.history.get(0);Exchange units=r.compoundOutput.prior;require(!units.clauses.isEmpty(),"actual symbolic unit mutation control");ResidualProof unit=units.clauses.get(0);org.kanger.ContextUniversalFrozenConstraints.Result wrong=units.checks.values().stream().filter(v->!v.proofs.contains(unit.proof)).findFirst().get();mutate(units,r.barrier,unit,"owner",wrong,"actual unit proof cannot be reassigned to another checked owner");yes(units,r.barrier);
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("compound-rebase-session-").toString());cases();System.out.println("CONTEXT_UNIVERSAL_COMPOUND_REBASE_SESSION_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
